#include <sys/resource.h>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <new>
#include <vector>

std::size_t g_allocs = 0;

void* operator new(std::size_t size) {
    ++g_allocs;
    if (void* p = std::malloc(size)) {
        return p;
    }
    throw std::bad_alloc();
}

void operator delete(void* p) noexcept {
    std::free(p);
}

long page_faults() {
    rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    return usage.ru_minflt;
}

struct Order {
    int64_t id;
    int64_t price_ticks;
    int64_t qty;
};

// The hot path: one order per tick, and a checksum so nothing is skipped.
int64_t on_ticks(std::vector<Order>& orders, int n) {
    int64_t checksum = 0;
    for (int i = 0; i < n; ++i) {
        orders.push_back(Order{i, 19275 + i % 7, 100});
        checksum += orders.back().price_ticks;
    }
    return checksum;
}

void measure(const char* name, std::vector<Order>& orders, int n) {
    std::size_t allocs = g_allocs;
    long faults = page_faults();
    int64_t checksum = on_ticks(orders, n);
    allocs = g_allocs - allocs;
    faults = page_faults() - faults;
    std::cout << name << ": " << allocs << " allocations, page faults: "
              << (faults > 0 ? "some" : "none") << ", checksum " << checksum << '\n';
}

int main() {
    const int n = 200000;

    std::vector<Order> cold;
    measure("cold", cold, n);

    std::vector<Order> reserved;
    reserved.reserve(n);
    measure("reserved", reserved, n);

    std::vector<Order> warm;
    warm.reserve(n);
    on_ticks(warm, n);  // warm-up: touch every page and run the code once
    warm.clear();       // size 0, capacity kept
    measure("warm", warm, n);
    return 0;
}

