// -O2
#include <pthread.h>
#include <sched.h>
#include <atomic>
#include <condition_variable>
#include <cstdint>
#include <iostream>
#include <mutex>
#include <thread>

inline void cpu_relax() {
#if defined(__x86_64__)
    __builtin_ia32_pause();  // x86: "this is a spin-wait"
#elif defined(__aarch64__)
    asm volatile("yield");   // the ARM64 hint
#endif
}

void spin_until(const std::atomic<int64_t>& value, int64_t want) {
    while (value.load(std::memory_order_acquire) != want) {
        cpu_relax();
    }
}

bool pin_to_cpu(int cpu) {
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(cpu, &set);
    return pthread_setaffinity_np(pthread_self(), sizeof(set), &set) == 0 && sched_getcpu() == cpu;
}

int main() {
    const int64_t rounds = 20000;
    std::atomic<int64_t> request{0}, reply{0};
    int64_t sum = 0;
    bool pinned = false;
    std::thread pong([&] {
        pinned = pin_to_cpu(sched_getcpu());  // the CPU it runs on is always allowed
        for (int64_t i = 1; i <= rounds; ++i) {
            spin_until(request, i);
            sum += i;
            reply.store(i, std::memory_order_release);
        }
    });
    for (int64_t i = 1; i <= rounds; ++i) {
        request.store(i, std::memory_order_release);
        spin_until(reply, i);
    }
    pong.join();
    std::cout << "pinned: " << (pinned ? "yes" : "no") << '\n';
    std::cout << "a core each for producer and consumer: "
              << (std::thread::hardware_concurrency() >= 2 ? "yes" : "no") << '\n';
    std::cout << "spinning: " << rounds << " round trips, sum " << sum << '\n';

    std::mutex m;
    std::condition_variable cv;
    int64_t turn = 0, blocked_sum = 0;  // odd: pong's turn, even: ping's
    std::thread sleeper([&] {
        for (int64_t i = 1; i <= rounds; ++i) {
            std::unique_lock<std::mutex> lock(m);
            cv.wait(lock, [&] { return turn == 2 * i - 1; });
            blocked_sum += i;
            turn = 2 * i;
            cv.notify_one();
        }
    });
    for (int64_t i = 1; i <= rounds; ++i) {
        std::unique_lock<std::mutex> lock(m);
        turn = 2 * i - 1;
        cv.notify_one();
        cv.wait(lock, [&] { return turn == 2 * i; });
    }
    sleeper.join();
    std::cout << "blocking: " << rounds << " round trips, sum " << blocked_sum << '\n';
    return 0;
}

