#include <array>
#include <atomic>
#include <cstddef>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <new>
#include <thread>

thread_local bool t_counting = false;  // true only on the hot thread
std::atomic<long> g_hot_allocs{0};

void* operator new(std::size_t size) {
    if (t_counting) g_hot_allocs.fetch_add(1, std::memory_order_relaxed);
    if (void* p = std::malloc(size)) return p;
    throw std::bad_alloc();
}

void operator delete(void* p) noexcept { std::free(p); }

template <typename T, std::size_t N>
class SpscQueue {
    static_assert(N >= 2 && (N & (N - 1)) == 0, "N must be a power of two");
public:
    bool push(const T& value) {
        const std::size_t tail = tail_.load(std::memory_order_relaxed);
        if (tail - head_.load(std::memory_order_acquire) == N) return false;
        slots_[tail & (N - 1)] = value;
        tail_.store(tail + 1, std::memory_order_release);
        return true;
    }
    bool pop(T& out) {
        const std::size_t head = head_.load(std::memory_order_relaxed);
        if (head == tail_.load(std::memory_order_acquire)) return false;
        out = slots_[head & (N - 1)];
        head_.store(head + 1, std::memory_order_release);
        return true;
    }
private:
    std::array<T, N> slots_{};
    std::atomic<std::size_t> head_{0};
    std::atomic<std::size_t> tail_{0};
};

struct LogRecord {
    const char* event;  // a string literal, which lives as long as the program
    int64_t order_id;
    int64_t price_ticks;
    int64_t qty;
};

int main() {
    SpscQueue<LogRecord, 1024> queue;
    long dropped = 0;

    std::thread logger([&] {  // the cold side: formats and writes
        LogRecord r;
        for (;;) {
            while (!queue.pop(r)) std::this_thread::yield();  // cold, so it may wait
            if (r.event == nullptr) break;  // the stop record
            std::cout << r.event << " id=" << r.order_id << " px=" << r.price_ticks << " qty=" << r.qty << '\n';
        }
    });

    std::thread hot([&] {  // the hot side: copies 32 bytes per log line
        t_counting = true;
        for (int64_t id = 1; id <= 4; ++id) {
            if (!queue.push(LogRecord{"new", id, 19275 + id, 100 * id})) ++dropped;
        }
        if (!queue.push(LogRecord{"fill", 2, 19277, 200})) ++dropped;
        while (!queue.push(LogRecord{nullptr, 0, 0, 0})) {}
    });

    hot.join();
    logger.join();
    std::cout << "hot thread: " << g_hot_allocs.load() << " allocations, " << dropped << " dropped\n";
    return 0;
}

