#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <random>
#include <vector>

// Nearest rank: the smallest sample with at least per_mille / 1000 of the
// sample at or below it. Integers, so no rounding decides the rank.
int64_t percentile(const std::vector<int64_t>& sorted, int per_mille) {
    std::size_t rank = (sorted.size() * per_mille + 999) / 1000;
    if (rank == 0) rank = 1;
    return sorted[rank - 1];
}

int main() {
    const int n = 100000;
    std::vector<int64_t> latency_ns;  // reserved up front: recording never allocates
    latency_ns.reserve(n);
    std::mt19937_64 rng(42);
    for (int i = 0; i < n; ++i) {
        int64_t ns = 700 + static_cast<int64_t>(rng() % 300);  // a normal tick
        if (rng() % 100 == 0) {
            ns += 2000 + static_cast<int64_t>(rng() % 3000);  // 1 in 100: cache misses
        }
        if (rng() % 2000 == 0) {
            ns += 40000;  // 1 in 2000: the OS took the core
        }
        latency_ns.push_back(ns);
    }

    int64_t total = 0;
    for (int64_t ns : latency_ns) total += ns;
    std::sort(latency_ns.begin(), latency_ns.end());  // after the run: the cold path

    std::cout << "mean   " << total / n << " ns\n";
    std::cout << "p50    " << percentile(latency_ns, 500) << " ns\n";
    std::cout << "p90    " << percentile(latency_ns, 900) << " ns\n";
    std::cout << "p99    " << percentile(latency_ns, 990) << " ns\n";
    std::cout << "p99.9  " << percentile(latency_ns, 999) << " ns\n";
    std::cout << "max    " << latency_ns.back() << " ns\n";
    return 0;
}

