#include <random>
#include <vector>

int64_t percentile(const std::vector<int64_t>& sorted, int per_mille) {
    std::size_t rank = (sorted.size() * per_mille + 999) / 1000;
    if (rank == 0) rank = 1;
    return sorted[rank - 1];
}

int main() {
    unsigned long long seed;
    int n;
    std::cin >> seed >> n;
    std::vector<int64_t> ack_ns;  // order sent to exchange ack, in nanoseconds
    ack_ns.reserve(n);
    std::mt19937_64 rng(seed);
    for (int i = 0; i < n; ++i) {
        int64_t ns = 9000 + static_cast<int64_t>(rng() % 2000);
        if (rng() % 50 == 0) ns += 15000 + static_cast<int64_t>(rng() % 10000);
        ack_ns.push_back(ns);
    }
    std::sort(ack_ns.begin(), ack_ns.end());
    std::cout << "p50 " << percentile(ack_ns, 500) << '\n';
    std::cout << "p99 " << percentile(ack_ns, 990) << '\n';
    std::cout << "p99.9 " << percentile(ack_ns, 999) << '\n';
    std::cout << "max " << ack_ns.back() << '\n';
    return 0;
}
